{
  "passageId": "dopamine-motor-control",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "도파민을 외부에서 섭취할 수는 있지만 뇌로 들어가지는 못한다는 한계를 제시하므로 양보·한계 관계이다."
    },
    {
      "id": "R2",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 유입 도파민이 장벽을 통과하지 못한다는 사실로부터 뇌의 신경 경로를 이동하는 도파민의 출처가 한정된다는 판단을 도출한다."
    },
    {
      "id": "R3",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 유입 도파민의 장벽 통과 불가를 근거로 뇌에서 신경 전달 물질로 작용할 수 있는 도파민의 범위를 판단한다."
    },
    {
      "id": "R4",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "신경 전달 물질의 일반적인 시냅스 신호 전달 원리를 도파민이라는 특정 물질의 전달 과정에 적용한다."
    },
    {
      "id": "R5",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 합성된 레보도파를 바탕으로 다음 단계의 도파민 합성이 진행되므로 과정·순서 관계이다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민 합성 이후 그 산출물의 저장·분비·신호 전달 단계가 이어진다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "저장이 분비를 일으킨다는 설명이 아니라 저장된 도파민이 이후 활성화 시 분비되는 차례를 제시한다."
    },
    {
      "id": "R8",
      "type": "CAUSE",
      "otherName": "",
      "reason": "도파민의 수용체 결합이 실제로 시냅스 후 뉴런에 신호가 전달되게 하는 작용을 설명한다."
    },
    {
      "id": "R9",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "신호 전달 활성에 미치는 영향이라는 같은 기준에서 D1 계열의 흥분 작용과 D2 계열의 억제 작용이 대립한다."
    },
    {
      "id": "R10",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D2 계열 수용체의 일반적인 억제 작용을 도파민성 뉴런에 위치한 자가 수용체의 경우에 적용한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "자가 수용체 결합에 따른 신호 전달 활성 억제가 실제로 도파민 분비 중단을 일으킨다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자가 수용체를 통해 분비가 중단되는 기작을 근거로 도파민성 뉴런의 자기 조절 능력을 판단한다."
    },
    {
      "id": "R13",
      "type": "PROCESS",
      "otherName": "",
      "reason": "분비된 도파민을 바탕으로 자가 수용체 결합과 활성 억제가 뒤따르는 경로를 연결한다."
    },
    {
      "id": "R14",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "분비된 도파민의 수용체 결합 경로와 DAT를 통한 재흡수 경로를 같은 층위의 서로 다른 처리 경로로 나란히 제시한다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민이 재흡수된 뒤 저장되어 재사용되는 후속 처리 단계로 이어진다."
    },
    {
      "id": "R16",
      "type": "PROCESS",
      "otherName": "",
      "reason": "도파민이 재흡수된 뒤 뉴런 안에서 분해되는 후속 처리 단계로 이어진다."
    },
    {
      "id": "R17",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "재사용과 뉴런 내 분해를 재흡수된 도파민의 두 가지 처리 방식으로 나란히 제시한다."
    },
    {
      "id": "R18",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "DAT에 의한 재흡수 설명에 대해 모든 도파민성 뉴런에 DAT가 있는 것은 아니라는 한계와 예외를 제시한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "도파민의 여러 기능 가운데 운동 조절을 수의적 운동의 조절로 더 구체적으로 밝힌다."
    },
    {
      "id": "R20",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "가바성 뉴런과 가바의 억제성이라는 일반적 성질을 직접 경로에서 내측 창백핵이 억제되는 경우에 적용한다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내측 창백핵 뉴런의 활성 억제가 시상으로의 가바 분비 중단을 실제로 일으킨다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상으로 가바가 분비되지 않는 것이 시상 뉴런의 억제 해제와 활성화를 일으킨다."
    },
    {
      "id": "R23",
      "type": "CAUSE",
      "otherName": "",
      "reason": "시상 글루타메이트성 뉴런의 활성화가 운동 영역으로의 글루타메이트 분비를 일으킨다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "운동 영역으로 분비된 글루타메이트가 실제로 운동의 시작을 유발한다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "간접 경로에서 분비된 글루타메이트가 내측 창백핵 뉴런의 활성화를 일으킨다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "문맥상 내측 창백핵 뉴런의 활성화가 직접 경로와 반대되는 후속 작용을 유발하는 기작을 설명한다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "직접 경로와 상반되는 간접 경로의 작용이 실제로 운동 차단으로 이어진다."
    },
    {
      "id": "R28",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "직접 경로와 간접 경로가 내측 창백핵의 활성 및 운동에 미치는 영향에서 서로 반대되는 값을 보인다."
    },
    {
      "id": "R29",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D1 계열 수용체의 흥분성이라는 일반 원리를 도파민의 직접 경로 활성화에 적용한다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로에 D1 계열 수용체가 밀집한다는 사실이 도파민에 의해 해당 경로가 활성화된다는 설명의 근거가 된다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "D2 계열 수용체의 억제성이라는 일반 원리를 도파민의 간접 경로 억제에 적용한다."
    },
    {
      "id": "R32",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로에 D2 계열 수용체가 밀집한다는 사실이 도파민에 의해 해당 경로가 억제된다는 설명의 근거가 된다."
    },
    {
      "id": "R33",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "직접 경로가 운동 시작을 이끈다는 사실은 그 경로를 활성화하는 도파민이 운동을 촉진한다는 결론을 뒷받침한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "간접 경로가 운동을 차단한다는 사실은 그 경로를 억제하는 도파민이 운동을 촉진한다는 결론을 뒷받침한다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "도파민에 의한 직접 경로 활성화와 간접 경로 억제가 실제로 목표 운동의 시작을 수월하게 한다."
    },
    {
      "id": "R36",
      "type": "CAUSE",
      "otherName": "",
      "reason": "목표 운동의 시작을 수월하게 하는 작용이 운동 촉진이라는 결과로 이어진다."
    }
  ]
}

